questionvariables.text:
/* Grouped data: 5 rainfall classes, width 10 */
lb: [0,10,20,30,40];
ub: [9,19,29,39,49];
cw: 10;  nc: 5;
/* Design-backwards: random frequencies 3..8 */
freq: makelist(rand(6)+3, i, 1, nc);
N: apply("+", freq);
/* Correct column values */
midpts: map(lambda([l,u],(l+u)/2), lb, ub);
fxs: map("*", freq, midpts);
sum_fx: apply("+", fxs);
cf: []; run: 0;
for i:1 thru nc do (run: run+freq[i], cf: endcons(run, cf));
mean_est: float(sum_fx / N);
mean_disp: round(mean_est*100)/100.0;
/* Modal class */
maxf: lmax(freq);
mode_idx: sublist_indices(freq, lambda([x], x=maxf))[1];
modal_interval: [lb[mode_idx], ub[mode_idx]];
/* Median (grouped interpolation; L = lower class limit - see audit report Decision 1) */
med_pos: N/2;
med_idx: 1;
for i:1 thru nc do (if cf[i] >= med_pos then (med_idx: i, return()));
L_med: lb[med_idx];
cf_prev: if med_idx=1 then 0 else cf[med_idx-1];
f_med: freq[med_idx];
median_est: float(L_med + ((med_pos - cf_prev)/f_med)*cw);
median_disp: round(median_est*100)/100.0;
